import { yupResolver } from "@hookform/resolvers/yup";
import { LoadingButton } from "@mui/lab";
import {
  Box,
  Button,
  Checkbox,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  FormControlLabel,
  FormHelperText,
  FormLabel,
  Grid,
  IconButton,
  InputAdornment,
  Radio,
  RadioGroup,
  TextField,
  Typography,
} from "@mui/material";
import CloseIcon from "mdi-material-ui/Close";
import { useEffect, useState } from "react";
import { Controller, useForm } from "react-hook-form";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import * as yup from "yup";
import { toastError, toastSuccess } from "src/utils/utils";
import ReactQuill from "react-quill";
import "react-quill/dist/quill.snow.css";
import { useParams } from "react-router-dom";

const validationSchema = yup.object().shape({
  title_1: yup
    .string()
    .trim()
    .required("Please add Title 1.")
    .max(20, "Title 1 must be at most 20 characters."),
  title_2: yup
    .string()
    .trim()
    .required("Please add Title 2.")
    .max(20, "Title 2 must be at most 20 characters."),
  title_3: yup
    .string()
    .trim()
    .required("Please add Title 3.")
    .max(20, "Title 3 must be at most 20 characters."),
});

const DialogOverviewFeaturesTitle = (props) => {
  const { mode, open, toggle, dataToEdit, onSuccess } = props;
  const [loading, setLoading] = useState(false);
  const [dialogTitle, setDialogTitle] = useState("");

  const { id } = useParams();
  const {
    control,
    handleSubmit,
    reset,
    setValue,
    formState: { errors },
  } = useForm({
    defaultValues: {
      title_1: "",
      title_2: "",
      title_3: "",
    },
    resolver: yupResolver(validationSchema),
    mode: "onChange",
  });

  useEffect(() => {
    if (open) {
      setLoading(false);
      setDialogTitle(
        mode === "add"
          ? "Add Overview Feature Title"
          : "Edit Overview Feature Title"
      );
      reset({
        title_1: dataToEdit?.title_1 || "",
        title_2: dataToEdit?.title_2 || "",
        title_3: dataToEdit?.title_3 || "",
      });
    }
  }, [dataToEdit, mode, open, reset]);

  const onSubmit = (data) => {
    let payload = {
      title_1: data.title_1,
      title_2: data.title_2,
      title_3: data.title_3,

      sub_it_solution_list_id: id,
    };

    setLoading(true);

    let apiInstance = null;

    if (mode === "edit") {
      apiInstance = axiosInstance.patch(
        ApiEndPoints.ITSolutionOverviewFeaturesTitle.edit(dataToEdit.id),
        payload,
        {}
      );
    } else {
      apiInstance = axiosInstance.post(
        ApiEndPoints.ITSolutionOverviewFeaturesTitle.create,
        payload,
        {}
      );
    }
    apiInstance
      .then((response) => response.data)
      .then((response) => {
        onSuccess();
        toastSuccess(response.message);
        toggle();
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  return (
    <>
      <Dialog open={open} fullWidth maxWidth="sm" scroll="paper">
        <DialogTitle
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <Box>{dialogTitle}</Box>
          <IconButton
            aria-label="close"
            onClick={toggle}
            sx={{ color: (theme) => theme.palette.grey[500] }}
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent
          sx={{ pb: 8, px: { sx: 8, sm: 15 }, pt: { xs: 8, sm: 12.5 } }}
        >
          <form id="hub-address-form" onSubmit={handleSubmit(onSubmit)}>
            <Grid container spacing={2}>
              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel
                    required
                    htmlFor="title_1"
                    error={Boolean(errors.title_1)}
                  >
                    Title 1
                  </FormLabel>
                  <Controller
                    name="title_1"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        placeholder="Enter Title 1"
                        onChange={onChange}
                        id="title_1"
                        value={value}
                        error={Boolean(errors.title_1)}
                      />
                    )}
                  />
                  {errors.title_1 && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.title_1.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel
                    required
                    htmlFor="title_2"
                    error={Boolean(errors.title_2)}
                  >
                    Title 2
                  </FormLabel>
                  <Controller
                    name="title_2"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        placeholder="Enter Title 2"
                        onChange={onChange}
                        id="title_2"
                        value={value}
                        error={Boolean(errors.title_2)}
                      />
                    )}
                  />
                  {errors.title_2 && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.title_2.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel
                    required
                    htmlFor="title_3"
                    error={Boolean(errors.title_3)}
                  >
                    Title 3
                  </FormLabel>
                  <Controller
                    name="title_3"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        placeholder="Enter Title 3"
                        onChange={onChange}
                        id="title_3"
                        value={value}
                        error={Boolean(errors.title_3)}
                      />
                    )}
                  />
                  {errors.title_3 && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.title_3.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
            </Grid>
          </form>
        </DialogContent>
        <DialogActions>
          <LoadingButton
            size="large"
            type="submit"
            form="hub-address-form"
            variant="contained"
            loading={loading}
          >
            Submit
          </LoadingButton>
          <Button size="large" variant="outlined" onClick={toggle}>
            Cancel
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default DialogOverviewFeaturesTitle;
