import Typography from "@mui/material/Typography";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import Box from "@mui/material/Box";
import IconButton from "@mui/material/IconButton";
import CustomDataGrid from "src/@core/components/data-grid";
import Chip from "@mui/material/Chip";
import { styled } from "@mui/material/styles";
import RemoveRedEyeIcon from "@mui/icons-material/RemoveRedEye";
import { useEffect, useState } from "react";

const TableOverviewFeatures = ({
  rows,
  totalCount,
  setCurrentPage,
  currentPage,
  setPageSize,
  pageSize,
  loading,
  toggleEdit,
  toggleDelete,
  onCellClick,
  tableHeader,
}) => {
  return (
    <>
      <CustomDataGrid
        loading={loading}
        rowCount={totalCount}
        rows={rows}
        handleCellClick={onCellClick}
        columns={[
          {
            field: "feature",
            minWidth: 400,
            flex: 1,
            sortable: false,
            headerName: `${tableHeader?.title_1}`,
            renderCell: ({ row }) => (
              <Typography noWrap variant="body2" title={row.feature}>
                {row.feature}
              </Typography>
            ),
          },
          {
            field: "is_native_tools",
            minWidth: 200,
            flex: 0.5,
            sortable: false,
            headerName: `${tableHeader?.title_2}`,
            renderCell: ({ row }) => (
              //   <Typography noWrap variant="body2" title={row.is_native_tools}>
              //     {row.is_native_tools}
              //   </Typography>
              <Chip
                label={row.is_native_tools ? "Yes" : "No"}
                sx={{
                  backgroundColor: row.is_native_tools
                    ? "#602de1c2"
                    : "default",
                  color: row.is_native_tools ? "#fff" : "inherit",
                }}
              />
            ),
          },
          {
            field: "is_plus",
            minWidth: 200,
            flex: 0.5,
            sortable: false,
            headerName: `${tableHeader?.title_3}`,
            renderCell: ({ row }) => (
              //   <Typography noWrap variant="body2" title={row.is_plus}>
              //     {row.is_plus}
              //   </Typography>
              <Chip
                label={row.is_plus ? "Yes" : "No"}
                sx={{
                  backgroundColor: row.is_plus ? "#602de1c2" : "default",
                  color: row.is_plus ? "#fff" : "inherit",
                }}
              />
            ),
          },
          {
            field: "Actions",
            flex: 0,
            minWidth: 130,
            sortable: false,
            headerName: "Actions",
            renderCell: ({ row }) => (
              <Box display="flex" alignItems="center" gap="10px">
                <IconButton
                  size="small"
                  color="primary"
                  variant="outlined"
                  onClick={(e) => {
                    e.stopPropagation();
                    toggleEdit(e, "edit", row);
                  }}
                >
                  <EditIcon />
                </IconButton>
                <IconButton
                  size="small"
                  color="secondary"
                  onClick={(e) => {
                    e.stopPropagation();
                    toggleDelete(e, "deleteTableData ", row);
                  }}
                >
                  <DeleteIcon />
                </IconButton>
              </Box>
            ),
          },
        ]}
        currentPage={currentPage}
        pageSize={pageSize}
        setCurrentPage={setCurrentPage}
        setPageSize={setPageSize}
      />
    </>
  );
};

export default TableOverviewFeatures;
